function $(i){return document.getElementById(i);}
function sv(i,v){const e=$(i);if(e)e.textContent=v;}
function setHexValue(id,v,fallback){const e=$(id);if(e){e.value=normalizeHexColor(v,fallback||e.defaultValue||'#ffffff').toUpperCase();if(e.__chip)e.__chip.style.background=e.value;}}
function normalizeHexColor(v,fallback){
  fallback=fallback||'#ffffff';
  v=String(v==null?'':v).trim();
  if(!v)return fallback;
  let m=v.match(/^#?([0-9a-fA-F]{3})$/);
  if(m){const a=m[1];return ('#'+a[0]+a[0]+a[1]+a[1]+a[2]+a[2]).toLowerCase();}
  m=v.match(/^#?([0-9a-fA-F]{6})$/);
  if(m)return ('#'+m[1]).toLowerCase();
  m=v.match(/^rgba?\s*\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})/i);
  if(m){
    const parts=[m[1],m[2],m[3]].map(n=>Math.max(0,Math.min(255,parseInt(n,10)||0)));
    return '#'+parts.map(n=>n.toString(16).padStart(2,'0')).join('');
  }
  return fallback;
}
function bindHexColorInputs(root){
  (root||document).querySelectorAll('input.hex-color').forEach(e=>{
    if(e.__hexBound)return;e.__hexBound=true;
    if(e.type!=='color'&&!(e.previousElementSibling&&e.previousElementSibling.classList&&e.previousElementSibling.classList.contains('bg-color-preview'))){
      const chip=document.createElement('span');chip.className='bg-color-preview hex-auto-chip';chip.title='Текущий цвет';
      if(e.parentNode)e.parentNode.insertBefore(chip,e);
      e.__chip=chip;
    }
    const syncChip=()=>{if(e.__chip)e.__chip.style.background=normalizeHexColor(e.value,e.dataset.fallback||e.defaultValue||'#ffffff');};
    const normalize=()=>{const old=e.value;const next=normalizeHexColor(old,e.dataset.fallback||e.defaultValue||'#ffffff');e.value=next.toUpperCase();e.classList.remove('invalid');syncChip();};
    e.value=normalizeHexColor(e.value||e.defaultValue||'#ffffff').toUpperCase();
    e.addEventListener('input',()=>{
      const v=String(e.value||'').trim();
      const ok=/^#?[0-9a-fA-F]{3}$/.test(v)||/^#?[0-9a-fA-F]{6}$/.test(v)||/^rgba?\s*\(/i.test(v);
      e.classList.toggle('invalid',!!v&&!ok);
      if(ok){e.value=normalizeHexColor(v,e.dataset.fallback||e.defaultValue||'#ffffff').toUpperCase();e.classList.remove('invalid');}
      syncChip();
    });
    e.addEventListener('change',normalize);
    e.addEventListener('blur',normalize);
    syncChip();
  });
}
document.addEventListener('DOMContentLoaded',()=>bindHexColorInputs(document));
let currentOrientation='portrait';
function setOrientation(or){
  currentOrientation=or;
  const hidden=$('cfg-orientation'); if(hidden) hidden.value=or;
  ['orientation-main','orientation-preview','orientation-editor'].forEach(id=>{const w=$(id); if(!w)return; w.querySelectorAll('.orbtn').forEach(b=>b.classList.toggle('on',b.dataset.or===or));});
  $('phone')?.classList.toggle('landscape',or==='landscape');
  $('editor-phone')?.classList.toggle('landscape',or==='landscape');
  const lab=$('phone-label'); if(lab) lab.textContent=(or==='landscape'?'844×844':'390×844')+' · нажми Update Preview после изменений';
  if(window.RiseLevelEditor)RiseLevelEditor.resize();
}
document.addEventListener('click',e=>{
  // End Card has its own orientation switch. Do not let it change the whole
  // builder orientation or overwrite the export orientation field.
  const b=e.target.closest('#orientation-main .orbtn[data-or],#orientation-preview .orbtn[data-or],#orientation-editor .orbtn[data-or]');
  if(b)setOrientation(b.dataset.or);
});

// Luna-like inspector: left side is navigation, right side contains settings
(function initInspector(){
  const ws=document.querySelector('.ws'), sb=document.querySelector('.sb');
  if(!ws||!sb)return;
  const inspector=document.createElement('aside');
  inspector.className='inspector';
  inspector.innerHTML='<div class="inspector-head" id="inspector-title">Player</div>';
  ['panel-player','panel-speed','panel-obstacles-physics','panel-prefab-physics','panel-timing','panel-endcard-gameplay','panel-main-ball','panel-shield','panel-obstacles-visual','panel-prefabs','panel-environment','panel-stage-accents','panel-text-fonts','panel-sounds'].forEach(id=>{const el=$(id); if(el) inspector.appendChild(el);});
  const bbar=document.querySelector('.bbar'); if(bbar) inspector.appendChild(bbar);
  ws.appendChild(inspector);
})();

// left accordions and parameter navigation
document.querySelectorAll('.acc-head[data-acc]').forEach(b=>{
  b.addEventListener('click',()=>{
    b.classList.toggle('on');
    const body=$('acc-'+b.dataset.acc); if(body) body.classList.toggle('on');
  });
});
document.querySelectorAll('.tab[data-panel]').forEach(b=>{
  b.addEventListener('click',()=>{
    document.querySelectorAll('.tab[data-panel]').forEach(x=>x.classList.remove('on'));
    document.querySelectorAll('.inspector .pnl').forEach(x=>x.classList.remove('on'));
    b.classList.add('on');
    const panel=$('panel-'+b.dataset.panel);
    if(panel) panel.classList.add('on');
    const t=$('inspector-title'); if(t)t.textContent=(panel&&panel.dataset.title)||b.textContent.trim();
  });
});

// right tabs
document.querySelectorAll('.rtab[data-rt]').forEach(b=>{
  b.addEventListener('click',()=>{
    document.querySelectorAll('.rtab[data-rt]').forEach(x=>x.classList.remove('on'));
    b.classList.add('on');
    const rt=b.dataset.rt;
    $('rp-preview').style.display=rt==='preview'?'':'none';
    $('rp-levels').classList.toggle('on',rt==='levels');
    const ep=$('rp-endcard'); if(ep)ep.classList.toggle('on',rt==='endcard');
    if(rt==='levels')LE.resize();
    if(rt==='endcard'&&window.RiseEndCardEditor)RiseEndCardEditor.resize();
  });
});

// sprites
function loadSpr(key,inp){
  const f=inp.files[0];if(!f)return;
  const r=new FileReader();
  r.onload=e=>{
    RiseBuilder.setSprite(key,e.target.result);
    document.querySelectorAll(`[id="th-${key}"],[id="th-${key}-visuals"],[id="th-${key}-level"]`).forEach(th=>th.innerHTML=`<img src="${e.target.result}">`);
    if(window.RiseLevelEditor)RiseLevelEditor.draw();
  };
  r.readAsDataURL(f);
}
function clearSpr(key){
  RiseBuilder.setSprite(key,null);
  document.querySelectorAll(`[id="th-${key}"],[id="th-${key}-visuals"],[id="th-${key}-level"]`).forEach(th=>{th.innerHTML=key==='player'?'<img src="Assets/textures/balloon.png" alt="balloon">':key==='shield'?'<img src="Assets/textures/controller.png" alt="controller">':key==='tutorial_hand'?'<img src="Assets/textures/tutorial_hand.svg" alt="tutorial hand">':key.indexOf('background')===0?'🖼️':key.indexOf('bg_seam')===0?'〰️':'⬛';});
  if(window.RiseLevelEditor)RiseLevelEditor.draw();
}


// Default sprites imported from the provided playable export.
const PLAYABLE_DEFAULT_SPRITES={"bg_seam_stage0":"data:image/png;base64,","bg_seam_stage1":"data:image/png;base64,","bg_seam_stage2":"data:image/png;base64,","bg_seam_stage3":"data:image/png;base64,","bg_seam_stage4":"data:image/png;base64,","bg_seam_stage5":"data:image/png;base64,","bg_seam_stage6":"data:image/png;base64,","bg_seam_stage7":"data:image/png;base64,","bg_seam_stage8":"data:image/png;base64,","bg_seam_stage9":"data:image/png;base64,","bg_seam_stage10":"data:image/png;base64,","bg_seam_stage11":"data:image/png;base64,","bg_seam_stage12":"data:image/png;base64,","bg_seam_stage13":"data:image/png;base64,","bg_seam_stage14":"data:image/png;base64,","bg_seam_stage15":"data:image/png;base64,","bg_seam_stage16":"data:image/png;base64,","bg_seam_stage17":"data:image/png;base64,","bg_seam_stage18":"data:image/png;base64,","bg_seam_stage19":"data:image/png;base64,","bg_seam_stage20":"data:image/png;base64,","bg_seam_stage21":"data:image/png;base64,","endcard_win":"data:image/png;base64,","endcard_win_frame":"data:image/png;base64,","endcard_lose_bg":"data:image/png;base64,","endcard_lose_logo":"data:image/png;base64,","endcard_lose_button":"data:image/png;base64,","background":"data:image/png;base64,","player":"data:image/png;base64,","shield":"data:image/png;base64,","player_death":"data:image/png;base64,","tutorial_triangle":"data:image/png;base64,","height_arrow":"data:image/png;base64,","endcard_countdown_badge":"data:image/png;base64,","endcard_lose_portrait_cta_bg":"data:image/png;base64,","endcard_lose_landscape_cta_bg":"data:image/png;base64,","endcard_win_portrait_cta_bg":"data:image/png;base64,","endcard_win_landscape_cta_bg":"data:image/png;base64,"};
// The playable already contains the exact Start, mini-level and Finish overlay sprites.
// Only fill genuinely missing generated rows as a backward-compatible fallback.
const PLAYABLE_DEFAULT_CLOUD_SPRITE=PLAYABLE_DEFAULT_SPRITES.bg_seam_stage1||PLAYABLE_DEFAULT_SPRITES.bg_seam_stage2||null;
if(PLAYABLE_DEFAULT_CLOUD_SPRITE){
  for(let i=1;i<=21;i++){
    const key='bg_seam_stage'+i;
    if(!PLAYABLE_DEFAULT_SPRITES[key])PLAYABLE_DEFAULT_SPRITES[key]=PLAYABLE_DEFAULT_CLOUD_SPRITE;
  }
}
function applyPlayableDefaultSprites(){
  try{Object.entries(PLAYABLE_DEFAULT_SPRITES).forEach(([k,v])=>{if(!v)return;RiseBuilder.setSprite(k,v);document.querySelectorAll(`[id=\"th-${k}\"],[id=\"th-${k}-visuals\"],[id=\"th-${k}-level\"]`).forEach(th=>{const im=document.createElement('img');im.src=v;th.replaceChildren(im);});});}catch(e){}
}
applyPlayableDefaultSprites();

