    shape='custom';mode='add';clearToolButtons();
    document.querySelectorAll('.et[data-shape]').forEach(x=>x.classList.remove('on'));
    const tab=document.querySelector('.tab[data-panel="obstacles-visual"]');if(tab)tab.click();
