        ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.setLineDash([5,4]);
        ctx.strokeRect(bx-w/2-6,by-h*.58-6,w+12,h+r*3.25+12);ctx.setLineDash([]);
