  bindPb('pb-w','baseW',v=>Math.max(20,parseFloat(v)||64));bindPb('pb-h','baseH',v=>Math.max(60,parseFloat(v)||300));bindPb('pb-fill','fill');bindPb('pb-line','line');bindPb('pb-appear','appear');bindPbOffset('pb-offx','anchorOffsetX');bindPbOffset('pb-offy','anchorOffsetY');
